from lib import *
S = SS('f180')
R = J('f180'); T = R['term']; SG = R['sigs']; G = R['gt1']; H = R['hup']
steps = [
    step(f"默认配置(graceful_timeout=30 秒)下,3 秒的请求正在处理时给 master 发 SIGTERM:这个请求照常完成 → {T['client']},耗时 {T['client_s']} s;master 在 {T['master_exit_s']} s 后退出,日志是 Handling signal: term → Worker exiting → Shutting down: Master。关闭开始 0.5 秒后再发新连接 → {T['new']}(监听已关,不再接新请求)。worker 里注册的 atexit 回调运行了({len(T['atexit'])} 次),gunicorn 的 worker_exit 钩子也触发了({len(T['hook'])} 次)。SIGTERM 是「处理完手上的再退出」。", t=tl(S(1)), done=lidx(S(1), '进行中的请求', '日志', 'atexit'), mark=lidx(S(1), '新连接'), kv=KV([['SIGTERM', '进行中的请求完成,再退出'], ['新连接', T['new']], ['atexit / worker_exit', '都运行']], ['SIGTERM'])),
    step(f"同一个请求换不同的信号:SIGTERM → {SG['SIGTERM']['client']},{SG['SIGTERM']['client_s']} s;SIGINT → {SG['SIGINT']['client']},{SG['SIGINT']['client_s']} s,master {SG['SIGINT']['master_exit_s']} s 就退出;SIGQUIT → {SG['SIGQUIT']['client']},{SG['SIGQUIT']['client_s']} s(与 SIGINT 一样是立即关闭,进行中的请求被打断,客户端收到的是 500 错误页);SIGKILL 发给 master → 请求仍然完成 {SG['SIGKILL']['client']},新连接也返回 {SG['SIGKILL']['new']}——worker 是独立进程,master 没了之后它继续服务,直到手上的请求结束才发现 master 不在了、自己退出(atexit {len(SG['SIGKILL']['atexit'])} 次)。kill -9 master 不是「停服务」,会留下孤儿 worker 占着端口。", t=tl(S(2)), done=lidx(S(2), 'SIGTERM  '), mark=lidx(S(2), 'SIGINT', 'SIGQUIT', 'SIGKILL'), b=bars([[k, SG[k]['client_s'], f"{SG[k]['client_s']} s"] for k in SG], 3.2, mark=[1, 2], done=[0, 3]), kv=KV([['SIGTERM', '优雅'], ['SIGINT / SIGQUIT', '立即,请求被打断'], ['SIGKILL master', 'worker 变孤儿继续服务']], ['SIGKILL master'])),
    step(f"graceful_timeout 比请求时间短时(--graceful-timeout 1,请求要 3 秒):SIGTERM 之后 1 秒左右 master 退出({G['master_exit_s']} s),进行中的请求 → {G['client']}({G['client_s']} s 后连接被断开),日志里只有 Handling signal 和 Shutting down,没有任何 Worker exiting 或超时的说明;worker 里的 atexit 与 worker_exit 钩子都没有运行(各 {len(G['atexit'])} 次)。超过这个时间 worker 是被直接杀掉的,清理代码不会执行。", t=tl(S(3)), done=lidx(S(3), '日志'), mark=lidx(S(3), '进行中的请求', 'atexit'), kv=KV([['graceful_timeout', '1 s(请求 3 s)'], ['请求', G['client']], ['atexit', f"{len(G['atexit'])} 次"]], ['请求'])),
    step(f"SIGHUP 是重载:3 秒的请求进行中、同时每 50 ms 发一次 /pid 请求,期间发 SIGHUP。HUP 前 {H['old']} 个 worker,HUP 后 {H['new']} 个,与之前重叠 {H['overlap']} 个(全部更换);进行中的请求 → {H['client']},{H['t']} s;期间 {H['n']} 次 /pid 请求失败 {H['bad']} 次,请求里先后见到 {H['seen']} 个不同的 worker pid(新旧交替);旧 worker 退出时 worker_exit 钩子 {H['hook']} 次、atexit {H['atexit']} 次都运行了。重载是滚动式的:新 worker 起来之后旧的才退出,所以不丢请求。", t=tl(S(4)), done=lidx(S(4), '进行中的 3 秒请求', 'worker_exit'), mark=lidx(S(4), 'HUP 之前'), kv=KV([['HUP', '新 worker 先起,旧的处理完再退'], ['失败请求', f"{H['bad']} / {H['n']}"]], ['失败请求'])),
]
A = mkartf('f180', 180, 'Flask,gunicorn,优雅关闭,信号,SIGHUP,真实验证,动画演示',
    f'用真实的 gunicorn 对同一个 3 秒请求发不同信号:SIGTERM 让请求完成({T["client_s"]} s)、SIGINT/SIGQUIT 立即打断(500)、SIGKILL master 后孤儿 worker 继续服务;graceful_timeout 小于请求时间时请求被断开且 atexit 不运行;SIGHUP 重载 {H["n"]} 次探测请求失败 {H["bad"]} 次。',
    '部署新版本时,正在处理的请求会怎么样?不同信号对 gunicorn 的效果差别很大。这篇用真实的 gunicorn,让一个 3 秒的请求处于进行中,逐个发信号,看请求结果、退出时间、atexit 和 worker_exit 钩子(容器里的信号传递见第 189 篇)。',
    [(f'{T["client_s"]} s', 'SIGTERM 时进行中的 3 秒请求正常完成'), ('500', 'SIGINT / SIGQUIT 时进行中的请求得到的状态码'), (f'{H["bad"]} / {H["n"]}', 'SIGHUP 重载期间失败的探测请求数')],
    [('SIGTERM', '<p>上一篇:<a href="flask-health-check.html">健康检查接口</a>;下一篇:<a href="flask-logging-config.html">日志配置</a>。</p><p>实验用 1 个 sync worker 与 2 个 worker 两种配置,请求是 <code>time.sleep(3)</code>。</p>'), ('不同信号', None), ('graceful_timeout', None), ('SIGHUP 重载', None)],
    steps, [ENV_F + '。gunicorn(sync worker),macOS', '没有验证:gthread/gevent worker 的关闭行为、长连接(keep-alive)与 SSE/WebSocket 的关闭、preload_app 下的 HUP、systemd/Kubernetes 的停止流程与 terminationGracePeriod、SIGUSR2 热升级、worker 超时(--timeout)与关闭的相互作用'], '优雅关闭')
